'use client'

import { useApolloClient } from '@apollo/client/react'
import { useRouter } from 'next/navigation'
import { useEffect, useRef, useState, type ReactElement } from 'react'
import { useForm } from 'react-hook-form'
import {
  ImportStatusDocument,
  RowErrorsDocument,
  type ImportJobSummaryFragment,
  type RowErrorsQuery,
} from '../../generated/graphql'
import { dateTime, errorMessage, label } from '../inventory-api'
import { StatusChip } from '../inventory-list'
import { useImportToken } from '../inventory-workspace'
import { isImportJobId, isOperatorToken } from './import-route'

const TERMINAL = new Set(['COMPLETED', 'COMPLETED_WITH_ERRORS', 'FAILED', 'EXPIRED'])

export function ImportJob({ jobId }: { jobId?: string }): ReactElement {
  const router = useRouter()
  const { token } = useImportToken()
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm({ defaultValues: { id: '' }, reValidateMode: 'onSubmit' })
  const [refresh, setRefresh] = useState(0)
  const lookupError = errors.id?.message
  const authorized = isOperatorToken(token)

  function openJob({ id }: { id: string }): void {
    if (id === jobId) {
      setRefresh((value) => value + 1)
    } else {
      router.push(`/imports/${encodeURIComponent(id)}`)
    }
  }

  return (
    <section className="card import-card" aria-labelledby="job-title">
      <h2 id="job-title">Import job</h2>
      <form className="lookup" onSubmit={handleSubmit(openJob)}>
        <label className="field">
          Job ID
          <input
            {...register('id', {
              setValueAs: (value: string) => value.trim().toLowerCase(),
              validate: (id) => isImportJobId(id) || 'Enter a valid import job ID.',
            })}
            aria-invalid={Boolean(lookupError)}
            aria-describedby={lookupError ? 'lookup-error' : undefined}
            placeholder="Paste a job ID"
          />
        </label>
        <button className="button button-secondary">
          Open
        </button>
      </form>
      {lookupError && (
        <p id="lookup-error" className="error" role="alert">
          {lookupError}
        </p>
      )}
      {!jobId && (
        <p className="subtle">Upload a file or open an existing job to view its progress.</p>
      )}
      {jobId && <p className="mono job-id">{jobId}</p>}
      {jobId && !authorized && (
        <p className="subtle">Enter your local operator token to view this job.</p>
      )}
      {jobId && authorized && (
        <ImportJobResults key={token} jobId={jobId} token={token} refresh={refresh} />
      )}
    </section>
  )
}

function ImportJobResults({ jobId, token, refresh }: {
  jobId: string
  token: string
  refresh: number
}): ReactElement {
  const client = useApolloClient()
  const [job, setJob] = useState<ImportJobSummaryFragment | null>(null)
  const [pollError, setPollError] = useState<string | null>(null)
  const [retry, setRetry] = useState(0)
  const [rowErrors, setRowErrors] = useState<RowErrorsQuery['importRowErrors'] | null>(null)
  const [errorsBusy, setErrorsBusy] = useState(false)
  const diagnosticsRequest = useRef<AbortController | null>(null)
  const [errorsMessage, setErrorsMessage] = useState<string | null>(null)

  useEffect(() => {
    const request = new AbortController()
    let timer: ReturnType<typeof setTimeout> | undefined
    async function poll(): Promise<void> {
      try {
        const { data } = await client.query({
          query: ImportStatusDocument,
          variables: { id: jobId },
          fetchPolicy: 'no-cache',
          context: {
            headers: { authorization: `Bearer ${token}` },
            fetchOptions: { signal: request.signal },
            queryDeduplication: false,
          },
        })
        if (request.signal.aborted) return
        if (!data) throw new Error('Inventory service returned no result.')
        const { importJob } = data
        setJob(importJob)
        setPollError(null)
        if (!TERMINAL.has(importJob.status)) timer = setTimeout(poll, 2500)
      } catch (error) {
        if (!request.signal.aborted) setPollError(errorMessage(error))
      }
    }
    void poll()
    return () => {
      request.abort()
      clearTimeout(timer)
    }
  }, [client, jobId, token, refresh, retry])

  useEffect(() => () => diagnosticsRequest.current?.abort(), [])

  async function showErrors(page: number): Promise<void> {
    diagnosticsRequest.current?.abort()
    const request = new AbortController()
    diagnosticsRequest.current = request
    setErrorsBusy(true)
    setErrorsMessage(null)
    try {
      const { data } = await client.query({
        query: RowErrorsDocument,
        variables: { id: jobId, page },
        fetchPolicy: 'no-cache',
        context: {
          headers: { authorization: `Bearer ${token}` },
          fetchOptions: { signal: request.signal },
          queryDeduplication: false,
        },
      })
      if (!data) throw new Error('Inventory service returned no result.')
      if (!request.signal.aborted) setRowErrors(data.importRowErrors)
    } catch (error) {
      if (!request.signal.aborted) {
        setErrorsMessage(errorMessage(error))
      }
    } finally {
      if (!request.signal.aborted) setErrorsBusy(false)
    }
  }

  return (
    <>
      {!job && !pollError && (
        <p role="status">Loading job…</p>
      )}
      {pollError && (
        <div className="callout" role="alert">
          <p className="error">{pollError}</p>
          <button
            onClick={() => {
              setPollError(null)
              setRetry((value) => value + 1)
            }}
            className="button button-secondary"
          >
            Refresh status
          </button>
        </div>
      )}
      {job && (
        <div className="job-summary" aria-live="polite">
          <StatusChip value={job.status} />
          {job.status === 'AWAITING_UPLOAD' && (
            <p className="subtle">Upload link expires {dateTime(job.uploadExpiresAt)}.</p>
          )}
          {job.finishedAt && <p className="subtle">Finished {dateTime(job.finishedAt)}.</p>}
          {job.forceOverwrite && <p className="subtle">Force overwrite requested.</p>}
          {job.failureCode && <p className="error">{label(job.failureCode)}</p>}
          <dl className="counts">
            <div>
              <dt>Read</dt>
              <dd>{job.rowsRead}</dd>
            </div>
            <div>
              <dt>Applied</dt>
              <dd>{job.rowsApplied}</dd>
            </div>
            <div>
              <dt>Unchanged</dt>
              <dd>{job.rowsUnchanged}</dd>
            </div>
            <div>
              <dt>Rejected</dt>
              <dd>{job.rowsRejected}</dd>
            </div>
          </dl>
          {!rowErrors && (
            <button
              className="button button-secondary"
              disabled={errorsBusy}
              onClick={() => showErrors(0)}
            >
              {errorsBusy ? 'Loading row errors…' : 'View row errors'}
            </button>
          )}
        </div>
      )}

      {(rowErrors || errorsMessage) && (
      <section className="diagnostics" aria-labelledby="errors-title">
        <div className="card-header">
          <h2 id="errors-title">Row errors</h2>
        </div>
        {errorsMessage && (
          <p className="panel-message error" role="alert">
            {errorsMessage}
          </p>
        )}
        {rowErrors?.items.length ? (
          <div className="table-scroll">
            <table>
              <thead>
                <tr>
                  <th scope="col">Row</th>
                  <th scope="col">Frame ID</th>
                  <th scope="col">Reason</th>
                  <th scope="col">Detail</th>
                </tr>
              </thead>
              <tbody>
                {rowErrors.items.map((row) => (
                  <tr key={`${row.rowNumber}-${row.code}`}>
                    <td>{row.rowNumber}</td>
                    <td>{row.frameId ?? '—'}</td>
                    <td>{label(row.code)}</td>
                    <td>{row.detail}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          rowErrors && (
            <p className="panel-message">
              No row errors are available. Diagnostics are kept for seven days after the job
              finishes.
            </p>
          )
        )}
        {rowErrors && (
          <footer className="pagination">
            <span>Page {rowErrors.page + 1}</span>
            <div>
              <button
                className="button button-secondary"
                disabled={!rowErrors.page || errorsBusy}
                onClick={() => showErrors(rowErrors.page - 1)}
              >
                Previous
              </button>
              <button
                className="button button-secondary"
                disabled={!rowErrors.hasNext || errorsBusy}
                onClick={() => showErrors(rowErrors.page + 1)}
              >
                Next
              </button>
              <button
                className="button button-secondary"
                disabled={errorsBusy}
                onClick={() => showErrors(rowErrors.page)}
              >
                Refresh
              </button>
            </div>
          </footer>
        )}
      </section>
      )}
    </>
  )
}

'use client'

import { useApolloClient } from '@apollo/client/react'
import { useParams, useRouter } from 'next/navigation'
import { useState, type ReactElement } from 'react'
import { useForm, useWatch } from 'react-hook-form'
import { CreateImportDocument, type CreateImportMutation } from '../../generated/graphql'
import { errorMessage } from '../inventory-api'
import { useImportToken } from '../inventory-workspace'
import { isOperatorToken } from './import-route'

type Upload = CreateImportMutation['createImportJob']
type UploadFields = {
  csv?: FileList
  force: boolean
  confirmed: boolean
}

const MAX_BYTES = 10 * 1024 * 1024

async function putCsv(upload: Upload, file: File): Promise<void> {
  const headers = new Headers(upload.uploadHeaders.map<[string, string]>(({ name, value }) => [name, value]))
  const response = await fetch(upload.uploadUrl, { method: 'PUT', headers, body: file })
  if (response.status === 412) return // A prior attempt already stored this one-write object.
  if (!response.ok) throw new Error(`Upload failed (HTTP ${response.status}).`)
}

export function ImportUpload(): ReactElement {
  const client = useApolloClient()
  const router = useRouter()
  const { jobId } = useParams<{ jobId?: string }>()
  const { token, setToken } = useImportToken()
  const {
    control,
    register,
    handleSubmit,
    resetField,
    setError,
    clearErrors,
    formState: { errors: uploadErrors, isSubmitting },
  } = useForm<UploadFields>({ defaultValues: { force: false, confirmed: false } })
  const force = useWatch({ control, name: 'force' })
  const [retrying, setRetrying] = useState(false)
  const [retryUpload, setRetryUpload] = useState<{ upload: Upload; file: File } | null>(null)

  const busy = isSubmitting || retrying
  const uploadError = uploadErrors.root?.upload?.message
  const canRetry = retryUpload !== null && retryUpload.upload.job.jobId === jobId

  async function submit({ csv, force, confirmed }: UploadFields): Promise<void> {
    if (busy) return
    const file = csv?.[0]
    if (!isOperatorToken(token)) {
      return setError('root.upload', { message: 'Enter a valid local operator token.' })
    }
    if (
      !file ||
      !file.name.toLowerCase().endsWith('.csv') ||
      file.size === 0 ||
      file.size > MAX_BYTES
    ) {
      return setError('root.upload', { message: 'Choose a non-empty CSV file up to 10 MiB.' })
    }
    if (force && !confirmed) {
      return setError('root.upload', { message: 'Confirm the forced overwrite before uploading.' })
    }
    setRetryUpload(null)
    const startingPath = window.location.pathname
    let created: Upload | undefined
    try {
      const { data } = await client.mutate({
        mutation: CreateImportDocument,
        variables: { force },
        fetchPolicy: 'no-cache',
        context: { headers: { authorization: `Bearer ${token}` } },
      })
      if (!data) throw new Error('Inventory service returned no result.')
      created = data.createImportJob
      resetField('confirmed')
      resetField('force')
      if (window.location.pathname === startingPath && created.job.jobId !== jobId) {
        router.push(`/imports/${encodeURIComponent(created.job.jobId)}`)
      }
      await putCsv(created, file)
    } catch (error) {
      setError('root.upload', { message: errorMessage(error) })
      if (created) setRetryUpload({ upload: created, file })
    }
  }

  async function retry(): Promise<void> {
    if (!retryUpload || busy) return
    const { upload, file: previousFile } = retryUpload
    if (Date.parse(upload.job.uploadExpiresAt) <= Date.now()) {
      setRetryUpload(null)
      return setError('root.upload', { message: 'This upload link expired. Start a new upload.' })
    }
    setRetrying(true)
    clearErrors('root.upload')
    try {
      await putCsv(upload, previousFile)
      setRetryUpload(null)
    } catch (error) {
      setError('root.upload', { message: errorMessage(error) })
    } finally {
      setRetrying(false)
    }
  }

  return (
  <section className="card import-card" aria-labelledby="upload-title">
    <h2 id="upload-title">New import</h2>
    <p className="subtle">
      DELTA applies rows in the file. Frames absent from the file stay as they are.
    </p>
    <form className="fields" onSubmit={handleSubmit(submit)}>
      <label className="field">
        Local operator token
        <input
          type="password"
          autoComplete="off"
          disabled={busy}
          value={token}
          onChange={(event) => {
            setRetryUpload(null)
            setToken(event.target.value)
          }}
        />
      </label>
      <label className="field file-field">
        Inventory CSV
        <input
          type="file"
          accept=".csv,text/csv"
          disabled={busy}
          {...register('csv', { onChange: () => setRetryUpload(null) })}
        />
        <span className="subtle">Up to 10 MiB and 10,000 data rows.</span>
      </label>
      <label className="check">
        <input
          type="checkbox"
          disabled={busy}
          {...register('force', { onChange: () => resetField('confirmed') })}
        />{' '}
        Force overwrite
      </label>
      {force && (
        <label className="check force-check">
          <input
            type="checkbox"
            disabled={busy}
            {...register('confirmed')}
          />
          I understand this can replace newer edits and restore manually deleted frames.
        </label>
      )}
      <div className="actions">
        <button type="submit" className="button button-primary" disabled={busy}>
          {busy ? 'Uploading…' : 'Upload CSV'}
        </button>
        {canRetry && (
          <button
            type="button"
            className="button button-secondary"
            disabled={busy}
            onClick={retry}
          >
            Retry upload
          </button>
        )}
      </div>
      {uploadError && (
        <p className="error" role="alert">
          {uploadError}
        </p>
      )}
    </form>
  </section>
  )
}
